const item = $input.first().json;

let raw = item.output || "";

raw = String(raw)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = {
    permission: "no",
    komment: "Ошибка AI-проверки: агент вернул невалидный JSON. Нужно проверить вручную."
  };
}

return [
  {
    json: {
      id: item.id,
      permission: parsed.permission === "yes" ? "yes" : "no",
      komment: parsed.komment || "Пустой комментарий от AI."
    }
  }
];

parameters.text:
=Ты AI-модератор изображений для Telegram-канала рецептов.

Твоя задача — проверить 6 изображений поста перед публикацией.

Проверяй только изображения. Текст поста используй только как контекст рецепта.

Текст поста:
{{ $json.post_text }}

Проверь изображения:
1. Нет ли заметных AI-артефактов.
2. Нет ли искажённой еды, рук, посуды, ингредиентов.
3. Нет ли странных объектов, визуального мусора или лишних предметов.
4. Нет ли водяных знаков, логотипов, рекламных надписей.
5. Если на изображениях есть текст — нет ли ошибок, ударений и странных символов.
6. Изображения должны быть пригодны для публикации.
7. Изображения должны выглядеть как связанный пошаговый процесс приготовления, а не случайный набор кадров.
8. Изображения должны соответствовать рецепту из текста поста.

Разделяй замечания на критические и некритические.

Критические замечания:
- заметные AI-артефакты;
- искажённые руки, еда, посуда или ингредиенты;
- ошибки в тексте на изображении;
- лишние надписи, водяные знаки, логотипы;
- изображение непригодно для публикации;
- изображения не похожи на пошаговый процесс;
- изображения не соответствуют рецепту.

Некритические замечания:
- мелкие визуальные помарки;
- слабая композиция;
- небольшая разница в стиле между кадрами;
- неидеальная резкость;
- небольшая неаккуратность, которая не мешает публикации.

Правила:
1. Если есть хотя бы одно критическое замечание — photo_permission = "no".
2. Если критических замечаний нет, но есть некритические — photo_permission = "yes".
3. Если замечаний нет — photo_permission = "yes", photo_komment = "без замечаний".

В photo_komment:
- если всё хорошо, напиши строго: "без замечаний";
- если есть замечания, кратко перечисли их;
- если проблема относится к конкретному кадру, укажи номер изображения;
- если есть критические и некритические замечания, раздели их явно.

Верни только JSON строго такого формата:

{
  "photo_permission": "yes",
  "photo_komment": "без замечаний"
}

parameters.jsCode:
const item = $input.first().json;

function findJsonText(obj) {
  if (typeof obj === "string") {
    if (
      obj.includes("photo_permission") ||
      obj.includes("photo_komment") ||
      obj.includes("permission") ||
      obj.includes("komment")
    ) {
      return obj;
    }
    return null;
  }

  if (Array.isArray(obj)) {
    for (const value of obj) {
      const found = findJsonText(value);
      if (found) return found;
    }
  }

  if (obj && typeof obj === "object") {
    for (const value of Object.values(obj)) {
      const found = findJsonText(value);
      if (found) return found;
    }
  }

  return null;
}

let raw = findJsonText(item);

if (!raw) {
  return [
    {
      json: {
        permission: "no",
        komment: "Ошибка проверки фото: JSON-ответ модели не найден."
      }
    }
  ];
}

raw = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .replace(/^json\s*/i, "")
  .trim();

const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start !== -1 && end !== -1 && end > start) {
  raw = raw.slice(start, end + 1);
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  return [
    {
      json: {
        permission: "no",
        komment: `Ошибка проверки фото: JSON найден, но не распарсился. Ответ модели: ${raw}`
      }
    }
  ];
}

return [
  {
    json: {
      permission: parsed.photo_permission || parsed.permission || "no",
      komment: parsed.photo_komment || parsed.komment || "Пустой комментарий от проверки фото."
    }
  }
];

